// Fast lookup structures
const SKILL_MAP_BY_ID = new Map(SKILL_CATALOGUE.map(s => [s.id, s]));
const SKILL_MAP_BY_NAME = new Map(SKILL_CATALOGUE.map(s => [s.name.toLowerCase(), s]));
const SKILL_MAP_BY_ALIAS = new Map();
SKILL_CATALOGUE.forEach(s => {
  (s.aliases || []).forEach(alias => {
    SKILL_MAP_BY_ALIAS.set(alias.toLowerCase(), s);
  });
});

export function findCatalogueSkill(input) {
  if (!input || typeof input !== 'string') return null;
  const cleaned = input.trim().toLowerCase();
  if (SKILL_MAP_BY_ID.has(cleaned)) return SKILL_MAP_BY_ID.get(cleaned);
  if (SKILL_MAP_BY_NAME.has(cleaned)) return SKILL_MAP_BY_NAME.get(cleaned);
  if (SKILL_MAP_BY_ALIAS.has(cleaned)) return SKILL_MAP_BY_ALIAS.get(cleaned);
  return null;
}

export function getCanonicalSkillName(input) {
  const match = findCatalogueSkill(input);
  return match ? match.name : input;
}
